import os, re, collections
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn); mods[p[:-5].replace('/','.')]=p
mods['AlgebraicJacobian']='AlgebraicJacobian.lean'
imp=collections.defaultdict(set)
for m,p in mods.items():
    for line in open(p,encoding='utf-8',errors='replace'):
        mm=re.match(r'^import\s+(AlgebraicJacobian[\w.]*)',line)
        if mm: imp[m].add(mm.group(1))
seen=set(); st=['AlgebraicJacobian']
while st:
    m=st.pop()
    if m in seen: continue
    seen.add(m); st.extend(d for d in imp[m] if d not in seen)
un=sorted(set(mods)-seen)
print(f"total={len(mods)} rooted={len(seen&set(mods))} UNROOTED={len(un)}")
for u in un: print("  ",u)
